package main

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

type Counter struct{ Value int }

func checkpoint(cart *Counter) {
	cart.Value++
	value := strconv.Itoa(cart.Value)
	temporary := os.Args[1] + ".next"
	if err := os.WriteFile(temporary, []byte(value), 0600); err == nil {
		_ = os.Rename(temporary, os.Args[1])
	}
	time.Sleep(30 * time.Millisecond)
}
func main() {
	fmt.Println("open Goland owned attach fixture")
	cart := &Counter{}
	for {
		checkpoint(cart)
	}
}

