package workflows

import "testing"

func TestOrdinary(t *testing.T) {
	t.Fatal("ordinary test must be excluded from benchmark and fuzz workflows")
}

func BenchmarkEcho(b *testing.B) {
	b.Run("small", func(b *testing.B) {
		for i := 0; i < b.N; i++ {
			Sink = Echo("中文 😀")
		}
	})
	b.Run("large", func(b *testing.B) {
		for i := 0; i < b.N; i++ {
			Sink = Echo("a longer string")
		}
	})
}

func BenchmarkOther(b *testing.B) { b.Fatal("unselected benchmark executed") }

func FuzzEcho(f *testing.F) {
	f.Add("seed")
	f.Add("中文 😀")
	f.Fuzz(func(t *testing.T, value string) {
		if Echo(value) != value {
			t.Fatalf("echo mismatch: %q", value)
		}
	})
}

func FuzzFailure(f *testing.F) {
	f.Add("seed")
	f.Fuzz(func(t *testing.T, value string) {
		if value != "seed" {
			t.Fatal("deterministic corpus failure")
		}
	})
}

